generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (COALESCE(?rebalanceCount, 0) AS ?rebalanceCount)
       (COALESCE(?goalCount, 0) AS ?goalCount)
       (COALESCE(?allocationCount, 0) AS ?allocationCount)
       (COALESCE(?avgRiskScore, 0) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?timeHorizon (COUNT(DISTINCT ?rebalance) AS ?rebalanceCount)
    WHERE {
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?rebalance wm:rebalancingActionOfInvestor ?inv .
    }
    GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?goal wm:belongsToInvestor ?inv .
    }
    GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (COUNT(DISTINCT ?alloc) AS ?allocationCount)
    WHERE {
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?alloc wm:allocationOfInvestor ?inv .
    }
    GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
    WHERE {
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?health wm:healthOfInvestor ?inv .
      ?health wm:riskScore ?riskScore .
    }
    GROUP BY ?timeHorizon
  }
}

